//! Both texts are baked into the binary: what ships through Homebrew is the bare
//! executable, with no LICENSE file beside it, so `--license` is the only place a
//! user can read them. THIRD-PARTY-NOTICES.txt is generated by
//! `scripts/generate-third-party-notices.sh`; `tests/third_party_notices.rs`
//! fails until it is run again after a dependency changes.

pub const LICENSE: &str = include_str!("../LICENSE");

pub const THIRD_PARTY_NOTICES: &str = include_str!("../THIRD-PARTY-NOTICES.txt");

pub fn license_text() -> String {
    let rule = "#".repeat(80);
    format!(
        "{rule}\n# piigrep\n{rule}\n\n{}\n\n{}",
        LICENSE.trim_end(),
        THIRD_PARTY_NOTICES
    )
}
